"""Experimental separation of contact-family analytic joins and mesh rows.

The prepared depth table, including every value and derivative, is retained.
Only the mesh's mandatory-break flag at an internal contact-family arc join
is removed. A complete old/new polygon correspondence check keeps the existing
50 micrometre limit. This is a guarded experiment, not a general continuity
claim: larger joins may fail that limit and must not count as successful fits.
"""
import bpy

from . import curved_mesh_boundary_nodes as bounds
from . import curved_continuation_nodes as continuation
from .curved_quad_fair_nodes import assign_group

c = bounds.c


def contact_join(g, corners, mouths, owner, t):
    """Identify a strictly interior, sampled contact-family two-arc join."""
    following = g.math('MODULO', owner + 1., c._count(g, mouths))
    la = c._read(g, mouths, 'st_cj_parameter', owner) - c._read(g, corners, 'st_cc_sa', owner)
    lb = c._read(g, mouths, 'st_cj_parameter', following) - c._read(g, corners, 'st_cc_sb', owner)
    arc = continuation.length(g, corners, owner)
    total = la + arc + lb
    first = c._read(g, corners, 'st_cc_radius', owner) * g.math(
        'ABSOLUTE', c._read(g, corners, 'st_cc_sweep', owner))
    join = (la + first) / g.math('MAXIMUM', total, 1e-12)
    family = c._read(g, corners, 'st_cj_contact_transition', owner, 'BOOLEAN')
    paired = g.math('COMPARE', c._read(g, corners, 'st_ct_kind', owner, 'INT'), 2.)
    internal = g.math('GREATER_THAN', t, la / total) * g.math('LESS_THAN', t, (la + arc) / total)
    at_join = g.math('LESS_THAN', g.math('ABSOLUTE', t - join), 2e-8)
    return family * paired * internal * at_join


def mesh_depths():
    name = 'Prochitecture Streets / Contact-family mesh-only knots v1'
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    g = c.Graph(name)
    for key in ('Corners', 'Mouths', 'Depths'):
        g.socket(key, 'NodeSocketGeometry')
    g.socket('Geometry', 'NodeSocketGeometry', 'OUTPUT')
    inp = g.node('NodeGroupInput')
    out = g.node('NodeGroupOutput')
    corners, mouths = inp.outputs['Corners'], inp.outputs['Mouths']
    owner = c.named(g, 'st_cg_owner', 'INT')
    t = c.named(g, 'st_cg_t')
    # Original source knots lie outside the arc interval. Strict inclusion
    # protects both arc endpoints, even when float rounding coincides with one.
    removed = contact_join(g, corners, mouths, owner, t) * c.named(g, 'st_cg_break', 'BOOLEAN')
    table = c._store(g, inp.outputs['Depths'], 'st_cg_mesh_join_removed', removed, 'BOOLEAN')
    table = c._store(g, table, 'st_cg_analytic_break', c.named(g, 'st_cg_break', 'BOOLEAN'), 'BOOLEAN')
    table = c._store(g, table, 'st_cg_break', c.named(g, 'st_cg_break', 'BOOLEAN') * (1. - removed), 'BOOLEAN')
    g.bind(table, out.inputs['Geometry'])
    return g.g


def counts(original, *, length_budget=False, lead_reservations=False):
    """Retain global counts; change only the filtered side's base allocation."""
    if lead_reservations and not length_budget:
        raise ValueError('Lead reservations require the contact count policy')
    name = original.name + ' / Original counts with contact mesh knots v1'
    if length_budget:
        name += ' / Reserved contact primitive v1'
        original = bounds.multi.plan(compound=False, continuations=True, length_budget=True,
                                    lead_reservations=lead_reservations)
    if lead_reservations:name += ' / Reserved lead intervals v1'
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    g = c.Graph(name)
    sockets = [s for s in original.interface.items_tree if s.item_type == 'SOCKET']
    for s in sockets:
        g.socket(s.name, s.socket_type, s.in_out, default=getattr(s, 'default_value', None))
    inp = g.node('NodeGroupInput')
    out = g.node('NodeGroupOutput')
    saved = g.node('GeometryNodeInputNamedAttribute')
    saved.data_type = 'BOOLEAN'
    saved.inputs['Name'].default_value = 'st_cg_analytic_break'
    analytic = c._store(g, inp.outputs['Depths'], 'st_cg_break', c.choose(g,
        saved.outputs['Exists'], saved.outputs['Attribute'], c.named(g, 'st_cg_break', 'BOOLEAN'), 'BOOLEAN'), 'BOOLEAN')
    calls = []
    for table in (analytic, inp.outputs['Depths']):
        call = g.node('GeometryNodeGroup')
        call.node_tree = original
        for s in sockets:
            if s.in_out == 'INPUT':
                g.bind(table if s.name == 'Depths' else inp.outputs[s.name], call.inputs[s.name])
        calls.append(call)
    index = c.V(g, g.node('GeometryNodeInputIndex').outputs[0])
    needed = c._read(g, calls[0].outputs['Geometry'], 'st_cq_count', index, 'INT')
    records = c._store(g, calls[1].outputs['Geometry'], 'st_cq_count', needed, 'INT')
    for s in sockets:
        if s.in_out == 'OUTPUT':
            value = records if s.name == 'Geometry' else calls[0].outputs[s.name]
            if s.name == 'Valid':
                value = c.V(g, value) * c.V(g, calls[1].outputs['Valid'])
            g.bind(value, out.inputs[s.name])
    return g.g


def counted_layout(original, *, length_budget=False, lead_reservations=False):
    name = original.name + ' / Retain common counts v1'
    if length_budget:
        name += ' / Reserved contact primitive v1'
    if lead_reservations:name += ' / Reserved lead intervals v1'
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    result = original.copy()
    result.name = name
    matches = [n for n in result.nodes if n.type == 'GROUP' and n.node_tree.name.startswith(
        'Prochitecture Streets / Ordinary cyclic quad counts v1')]
    if len(matches) != 1:
        raise ValueError('Expected one ordinary common-count plan')
    assign_group(matches[0], counts(matches[0].node_tree, length_budget=length_budget,
                                  lead_reservations=lead_reservations))
    return result


def blended_stations():
    """Blend equal-count station lists, leaving the analytic side unchanged."""
    name = 'Prochitecture Streets / Continuous contact mesh stations v1'
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    g = c.Graph(name)
    original = bounds.four.stations()
    sockets = [s for s in original.interface.items_tree if s.item_type == 'SOCKET']
    for s in sockets:
        g.socket(s.name, s.socket_type, s.in_out, default=getattr(s, 'default_value', None))
    g.socket('Blend', 'NodeSocketFloat', default=1.)
    inp = g.node('NodeGroupInput'); out = g.node('NodeGroupOutput')
    owner = c.V(g, inp.outputs['Index'])
    analytic = c._store(g, inp.outputs['Depths'], 'st_cg_break', c.named(g, 'st_cg_analytic_break', 'BOOLEAN'), 'BOOLEAN')
    knots = bounds.four._knots(g, analytic, owner)
    index = c.V(g, g.node('GeometryNodeInputIndex').outputs[0])
    following = c._read(g, knots, 'st_cg_t', g.math('MINIMUM', index+1., c._count(g, knots)-1.))
    length = c._read(g, inp.outputs['Plan'], 'st_cq_length', owner)
    cell = g.math('MAXIMUM', c.V(g, inp.outputs['Cell Size']), .02)
    base = c._stat(g, knots, g.math('CEIL', g.math('MAXIMUM', 0., following-c.named(g, 'st_cg_t'))*length/cell), 'Sum')
    # This call reads only the requested owner's record. The shared count and
    # all original physical lengths remain unchanged; only its base differs.
    analytic_plan = c._store(g, inp.outputs['Plan'], 'st_cq_base', base, 'INT')
    calls = []
    for table, plan in ((analytic, analytic_plan), (inp.outputs['Depths'], inp.outputs['Plan'])):
        call = g.node('GeometryNodeGroup'); call.node_tree = original
        for key in ('Index', 'Cell Size', 'Input Valid'): g.bind(inp.outputs[key], call.inputs[key])
        g.bind(table, call.inputs['Depths']); g.bind(plan, call.inputs['Plan'])
        calls.append(call)
    a = c._read(g, calls[0].outputs['Geometry'], 'st_cq_t', index)
    b = c._read(g, calls[1].outputs['Geometry'], 'st_cq_t', index)
    weight = c.bounded(g, c.V(g, inp.outputs['Blend']))
    geometry = c._store(g, calls[1].outputs['Geometry'], 'st_cq_t', a+(b-a)*weight)
    previous = c._read(g, geometry, 'st_cq_t', g.math('MAXIMUM', index-1., 0.))
    valid = c.V(g, calls[0].outputs['Valid'])*c.V(g, calls[1].outputs['Valid'])
    valid *= g.math('COMPARE', c._count(g, calls[0].outputs['Geometry']), c._count(g, geometry))
    valid *= c._stat(g, geometry, c.choose(g, g.math('LESS_THAN', index, .5), True,
        g.math('GREATER_THAN', c.named(g, 'st_cq_t')-previous, 1e-8), 'BOOLEAN'))
    g.bind(geometry, out.inputs['Geometry']); g.bind(valid, out.inputs['Valid'])
    return g.g


def blended_layout(original, *, lead_reservations=False, balanced_leads=False, fixed_leads=False, blend_stations=False):
    name = original.name + (' / Reserved lead contact stations v1' if lead_reservations else
                            ' / Continuous contact mesh stations v1')
    if balanced_leads:name+=' / Stable weighted leads v2'
    if fixed_leads:name+=' / Fixed equal lead rows v1'
    if lead_reservations and blend_stations:name+=' / Bounded station movement v1'
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    result = original.copy(); result.name = name
    if not lead_reservations or blend_stations:
        socket = result.interface.new_socket(name='Contact Blend', in_out='INPUT', socket_type='NodeSocketFloat')
        socket.default_value = 1.; socket.min_value = 0.; socket.max_value = 1.
    inp, = [n for n in result.nodes if n.type == 'GROUP_INPUT']
    stations = [n for n in result.nodes if n.type == 'GROUP' and n.node_tree == bounds.four.stations()]
    if len(stations) != 2:
        raise ValueError('Expected the two direct cyclic station callers')
    for node in stations:
        if lead_reservations:
            from .curved_contact_pattern_station_nodes import build
            assign_group(node, build(balanced_leads=balanced_leads,fixed_leads=fixed_leads,blend_stations=blend_stations))
            for key in ('Corners','Mouths'):result.links.new(inp.outputs[key],node.inputs[key])
            if blend_stations:result.links.new(inp.outputs['Contact Blend'],node.inputs['Blend'])
        else:
            assign_group(node, blended_stations())
            result.links.new(inp.outputs['Contact Blend'], node.inputs['Blend'])
    return result


def layout(original, *, preserve_counts=False, length_budget=False, blend_stations=False, lead_reservations=False, balanced_leads=False, fixed_leads=False):
    if balanced_leads and fixed_leads:raise ValueError('Select one lead allocation rule')
    if (balanced_leads or fixed_leads) and not lead_reservations:raise ValueError('Lead allocation requires reserved contact stations')
    if (blend_stations or lead_reservations) and not length_budget:
        raise ValueError('Continuous contact stations require a shared reserved count')
    if not ('Curb continuations' in original.name and 'Original Section ports' in original.name):
        raise ValueError('Requires ordinary original-port continuation charts')
    if any(key in original.name for key in ('Original span sides', 'Original chain sides')):
        raise ValueError('Multi-site charts require their own analytic join identities')
    name = original.name + ' / Bounded contact mesh knots v1'
    if preserve_counts:
        name += ' / Original counts'
    if length_budget:
        name += ' / Reserved contact primitive v1'
    if blend_stations:
        name += ' / Continuous stations v1'
    if lead_reservations:name += ' / Reserved lead intervals v1'
    if balanced_leads:name += ' / Stable weighted leads v2'
    if fixed_leads:name += ' / Fixed equal lead rows v1'
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    g = c.Graph(name)
    sockets = [s for s in original.interface.items_tree if s.item_type == 'SOCKET']
    for s in sockets:
        g.socket(s.name, s.socket_type, s.in_out, default=getattr(s, 'default_value', None))
    inp = g.node('NodeGroupInput')
    out = g.node('NodeGroupOutput')
    table = g.node('GeometryNodeGroup', 'Keep analytic coefficients; decouple only the internal mesh join')
    table.node_tree = mesh_depths()
    for key in ('Corners', 'Mouths', 'Depths'):
        g.bind(inp.outputs[key], table.inputs[key])
    raw = g.node('GeometryNodeGroup', 'Same direct quad construction with mesh-only knots')
    raw.node_tree = counted_layout(original, length_budget=length_budget,lead_reservations=lead_reservations) if preserve_counts or length_budget else original
    if lead_reservations:raw.node_tree=blended_layout(raw.node_tree,lead_reservations=True,balanced_leads=balanced_leads,fixed_leads=fixed_leads,blend_stations=blend_stations)
    weight = None
    if blend_stations:
        if not lead_reservations:raw.node_tree = blended_layout(raw.node_tree)
        proposal = g.node('GeometryNodeGroup', 'Measure the complete unblended proposal; not an acceptance test')
        proposal.node_tree = bounds.build(interpolation='Exact entrance rays' in original.name,
                                          contact_length_budget=True, measure_only=True,
                                          contact_lead_reservations=lead_reservations,
                                          balanced_leads=balanced_leads,fixed_leads=fixed_leads)
        for key in ('Sources', 'Mapping', 'Approaches', 'Corners', 'Mouths', 'Depths', 'Cell Size', 'Input Valid'):
            g.bind(inp.outputs[key], proposal.inputs[key])
        g.bind(table.outputs['Geometry'], proposal.inputs['Spaced Depths'])
        error = c.V(g, proposal.outputs['Maximum Difference'])
        # A heuristic weight, NOT a certificate. Re-evaluate both complete
        # polygons at the blended parameters and apply the original bound.
        weight = g.math('MINIMUM', 1., g.math('DIVIDE', .25*bounds.LOCAL_BOUND,
                                            g.math('MAXIMUM', error, 1e-12)))
        if lead_reservations:
            # Relocating many lead rows can move a polygon's maximum between
            # intervals, so its error need not scale linearly with this weight.
            # Quadratic damping keeps proposals already inside the reserved
            # budget unchanged, and retreats faster toward the original list
            # when they exceed it. The complete final check remains mandatory.
            weight=weight*weight
        g.bind(weight, raw.inputs['Contact Blend'])
    check = g.node('GeometryNodeGroup', 'Unchanged complete 50 micrometre polygon bound')
    check.node_tree = bounds.build(interpolation='Exact entrance rays' in original.name,
                                   preserve_contact_counts=preserve_counts,
                                   contact_length_budget=length_budget, contact_blend=blend_stations,
                                   contact_lead_reservations=lead_reservations,balanced_leads=balanced_leads,fixed_leads=fixed_leads)
    for key in ('Sources', 'Mapping', 'Approaches', 'Corners', 'Mouths', 'Depths', 'Cell Size', 'Input Valid'):
        g.bind(inp.outputs[key], check.inputs[key])
    g.bind(table.outputs['Geometry'], check.inputs['Spaced Depths'])
    if blend_stations:
        g.bind(weight, check.inputs['Blend'])
    for s in sockets:
        if s.in_out == 'INPUT':
            g.bind(table.outputs['Geometry'] if s.name == 'Depths' else inp.outputs[s.name], raw.inputs[s.name])
        else:
            value = raw.outputs[s.name]
            if s.socket_type == 'NodeSocketBool':
                value = c.V(g, value) * c.V(g, check.outputs['Valid'])
                if blend_stations: value *= c.V(g, proposal.outputs['Valid'])
            elif s.socket_type == 'NodeSocketGeometry':
                value = c._store(g, value, 'st_cq_contact_mesh_bound', check.outputs['Maximum Difference'])
                value = c._store(g, value, 'st_cq_contact_mesh_bound_valid', check.outputs['Valid'], 'BOOLEAN')
                if blend_stations: value = c._store(g, value, 'st_cq_contact_blend', weight)
            g.bind(value, out.inputs[s.name])
    if original.get('st_initial_samples_only'):
        # This wrapper preserves the source interface and adds only sampling
        # validation; it does not restore any omitted raw pavement outputs.
        g.g['st_initial_samples_only']=1
    return g.g


def checked_adapter(original, *, blend_stations=False):
    """Compose both sampling-error bounds inside the existing 0.1 mm limit."""
    name = original.name + ' / Combined sampling budget v1'
    if blend_stations: name += ' / Continuous stations v1'
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    g = c.Graph(name)
    sockets = [s for s in original.interface.items_tree if s.item_type == 'SOCKET']
    for s in sockets:
        g.socket(s.name, s.socket_type, s.in_out, default=getattr(s, 'default_value', None))
    inp = g.node('NodeGroupInput')
    out = g.node('NodeGroupOutput')
    call = g.node('GeometryNodeGroup', 'Corner pattern with complete sampling-error accounting')
    call.node_tree = original
    for s in sockets:
        if s.in_out == 'INPUT':
            g.bind(inp.outputs[s.name], call.inputs[s.name])
    first = c._stat(g, call.outputs['Plan'], c.named(g, 'st_cq_contact_mesh_bound'), 'Max')
    second = c._stat(g, call.outputs['Inspection Geometry'], c.named(g, 'st_cq_band_boundary_bound'), 'Max')
    total = first + second
    valid = g.math('LESS_THAN', total, 1e-4)
    for s in sockets:
        if s.in_out == 'OUTPUT':
            value = call.outputs[s.name]
            if s.socket_type == 'NodeSocketBool':
                value = c.V(g, value) * valid
            elif s.socket_type == 'NodeSocketGeometry':
                value = c._store(g, value, 'st_cq_combined_sampling_bound', total)
                if blend_stations:
                    value = c._store(g, value, 'st_cq_contact_blend',
                                     c._stat(g, call.outputs['Plan'], c.named(g, 'st_cq_contact_blend'), 'Min'))
            g.bind(value, out.inputs[s.name])
    return g.g


def replace_saved(root, *, preserve_counts=False, length_budget=False, blend_stations=False, lead_reservations=False, balanced_leads=False, fixed_leads=False):
    """Copy only participating local adapters; retain the original fallback."""
    memo, changed = {}, []

    def visit(tree):
        if tree in memo:
            return memo[tree]
        if tree.name.startswith('Prochitecture Streets / Local corner layout adapter v1'):
            raw, = [n for n in tree.nodes if n.type == 'GROUP' and
                    n.label == 'Original analytic boundary and ray samples; no interior descent']
            eligible = ('Curb continuations' in raw.node_tree.name and not any(
                key in raw.node_tree.name for key in ('Original span sides', 'Original chain sides')))
            result = tree.copy() if eligible else tree
            if eligible:
                assign_group(result.nodes[raw.name], layout(raw.node_tree, preserve_counts=preserve_counts,
                                                          length_budget=length_budget, blend_stations=blend_stations,
                                                          lead_reservations=lead_reservations,balanced_leads=balanced_leads,fixed_leads=fixed_leads))
                changed.append(tree.name)
                result = checked_adapter(result, blend_stations=blend_stations)
        else:
            children = [(n.name, visit(n.node_tree)) for n in tree.nodes if n.type == 'GROUP' and n.node_tree]
            children = [(name, child) for name, child in children if tree.nodes[name].node_tree != child]
            result = tree.copy() if children else tree
            for name, child in children:
                assign_group(result.nodes[name], child)
        memo[tree] = result
        return result

    result = visit(root)
    if not changed:
        raise ValueError('No ordinary contact-family corner adapters found')
    return result, sorted(set(changed))
